/**
 * 人工覆盖（2026-09-29 真机验证补漏）：一简对多繁按现代台港日常/金融语境取常用义，
 * 优先级高于上面的默认表。
 * - 稳→穩 / 连→連：默认单字表本就正确，显式锁定防回归
 * - 着→著：默认单字表缺失；作语气/动态助词时一律著（拿着/别急着/标志着…）
 * - 佣→傭：默认单字表缺失；金融语境"佣金"繁体作傭金
 * 另：词组目标里残留的简体"着"（短语匹配优先于单字回退，只靠单字覆盖修不到）一并正为"著"；
 * 同理"佣"在"佣金/回佣"等词组目标里残留，一并正为"傭"。
 */
const CHAR_OVERRIDE: Array<[string, string]> = [
  ['稳', '穩'],
  ['着', '著'],
  ['连', '連'],
  ['佣', '傭'],
];
for (const [cs, ct] of CHAR_OVERRIDE) charMap.set(cs, ct);
for (const [k, v] of phraseMap) {
  let fixed = v;
  if (fixed.indexOf('着') >= 0) fixed = fixed.replace(/着/g, '著');
  if (fixed.indexOf('佣') >= 0) fixed = fixed.replace(/佣/g, '傭');
  if (fixed !== v) phraseMap.set(k, fixed);
}

const MAX_PHRASE = 15;

/** 简体中文 -> 繁体中文（贪心最长词组匹配，失败回退单字映射；按码点迭代） */
export function toHant(s: string): string {
  if (!s) return s;
  const chs = [...s];
  const n = chs.length;
  let out = '';
  let i = 0;
  while (i < n) {
    let hit: string | undefined;
    const maxL = Math.min(MAX_PHRASE, n - i);
    for (let L = maxL; L >= 2; L--) {
      const v = phraseMap.get(chs.slice(i, i + L).join(''));
      if (v !== undefined) {
        hit = v;
        i += L;
        break;
      }
    }
    if (hit === undefined) {
      hit = charMap.get(chs[i]) ?? chs[i];
      i += 1;
    }
    out += hit;
  }
  return out;
}

/**
 * 三元收敛：`en ? a : b` 一律改写为 `tx(lang, a, b)`。
 * en -> 英文；hant -> 繁体（由简体分支转换）；其余 -> 简体原文。
 */
export function tx(lang: string, enText: string, zhText: string): string {
  if (lang === 'en') return enText;
  if (lang === 'hant') return toHant(zhText);
  return zhText;
}

/** 纯中文字符串的繁体条件转换（JSX 手工点用）：`zh2hant(lang, '中文')` */
export function zh2hant(lang: string, s: string): string {
  return lang === 'hant' ? toHant(s) : s;
}

/** 递归转换对象/数组中的所有字符串值（键名不动，供服务端 API 返回前调用） */
export function toHantDeep<T>(value: T): T {
  if (typeof value === 'string') return toHant(value) as unknown as T;
  if (Array.isArray(value)) return value.map(toHantDeep) as unknown as T;
  if (value !== null && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const k of Object.keys(value)) {
      out[k] = toHantDeep((value as Record<string, unknown>)[k]);
    }
    return out as unknown as T;
  }
  return value;
}
